## 설계 개요

구성은 다음처럼 나눕니다.

- `AIProvider` 인터페이스: 모든 provider가 동일한 계약을 따르도록 함
- `ProviderResult`: 표준 응답 포맷
- `ProviderError`: 표준 에러 포맷
- `orchestrateAI()`: provider 목록을 순서대로 시도, 실패 시 fallback
- `withTimeout()`, `sleep()`, `isRetryableError()` 등 유틸
- 예시 provider:
  - `OpenAIProvider`
  - `AnthropicProvider`
  - `MockProvider`

---

## 코드

```ts
// ai-orchestrator.ts

type Role = "system" | "user" | "assistant";

export interface ChatMessage {
  role: Role;
  content: string;
}

export interface AIRequest {
  messages: ChatMessage[];
  temperature?: number;
  maxTokens?: number;
  signal?: AbortSignal;
  metadata?: Record<string, unknown>;
}

export interface AIUsage {
  inputTokens?: number;
  outputTokens?: number;
  totalTokens?: number;
}

export interface ProviderResult {
  provider: string;
  model: string;
  content: string;
  usage?: AIUsage;
  latencyMs: number;
  finishReason?: string;
  raw?: unknown;
}

export type ProviderErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "BAD_REQUEST"
  | "UNAVAILABLE"
  | "NETWORK"
  | "INTERNAL"
  | "UNKNOWN";

export class ProviderError extends Error {
  public readonly provider: string;
  public readonly code: ProviderErrorCode;
  public readonly status?: number;
  public readonly retryable: boolean;
  public readonly cause?: unknown;

  constructor(params: {
    provider: string;
    message: string;
    code: ProviderErrorCode;
    retryable: boolean;
    status?: number;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "ProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.retryable = params.retryable;
    this.status = params.status;
    this.cause = params.cause;
  }
}

export interface AIProvider {
  name: string;
  model: string;
  generate(request: AIRequest): Promise<ProviderResult>;
}

export interface Logger {
  info(message: string, meta?: Record<string, unknown>): void;
  warn(message: string, meta?: Record<string, unknown>): void;
  error(message: string, meta?: Record<string, unknown>): void;
}

export const consoleLogger: Logger = {
  info: (message, meta) => console.log(`[INFO] ${message}`, meta ?? {}),
  warn: (message, meta) => console.warn(`[WARN] ${message}`, meta ?? {}),
  error: (message, meta) => console.error(`[ERROR] ${message}`, meta ?? {}),
};

export interface RetryPolicy {
  maxAttempts: number; // 총 시도 횟수, 1이면 재시도 없음
  baseDelayMs: number;
  maxDelayMs: number;
  backoffMultiplier: number;
}

export interface OrchestratorOptions {
  timeoutMs: number;
  retryPolicy: RetryPolicy;
  logger?: Logger;
  stopOnNonRetryableError?: boolean;
}

export interface AttemptFailure {
  provider: string;
  model: string;
  error: {
    name: string;
    message: string;
    code?: string;
    status?: number;
    retryable?: boolean;
  };
}

export interface OrchestrationResult {
  success: true;
  result: ProviderResult;
  attempts: AttemptFailure[];
}

export interface OrchestrationFailure {
  success: false;
  attempts: AttemptFailure[];
  finalError: ProviderError;
}

export type OrchestrationResponse = OrchestrationResult | OrchestrationFailure;

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function computeBackoffDelay(
  attempt: number,
  policy: RetryPolicy
): number {
  const raw = policy.baseDelayMs * Math.pow(policy.backoffMultiplier, attempt - 1);
  const jitter = Math.random() * 100;
  return Math.min(raw + jitter, policy.maxDelayMs);
}

function withTimeout<T>(
  promiseFactory: (signal: AbortSignal) => Promise<T>,
  timeoutMs: number,
  externalSignal?: AbortSignal
): Promise<T> {
  const controller = new AbortController();

  const onAbort = () => controller.abort(externalSignal?.reason);
  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort(externalSignal.reason);
    } else {
      externalSignal.addEventListener("abort", onAbort, { once: true });
    }
  }

  const timeout = setTimeout(() => {
    controller.abort(new Error(`Timed out after ${timeoutMs}ms`));
  }, timeoutMs);

  return promiseFactory(controller.signal)
    .finally(() => {
      clearTimeout(timeout);
      if (externalSignal) {
        externalSignal.removeEventListener("abort", onAbort);
      }
    });
}

function normalizeUnknownError(provider: string, err: unknown): ProviderError {
  if (err instanceof ProviderError) return err;

  if (err instanceof Error && err.name === "AbortError") {
    return new ProviderError({
      provider,
      message: err.message || "Request aborted",
      code: "TIMEOUT",
      retryable: true,
      cause: err,
    });
  }

  return new ProviderError({
    provider,
    message: err instanceof Error ? err.message : "Unknown provider error",
    code: "UNKNOWN",
    retryable: true,
    cause: err,
  });
}

function isRetryableError(err: ProviderError): boolean {
  return err.retryable;
}

async function executeWithRetry(
  provider: AIProvider,
  request: AIRequest,
  options: OrchestratorOptions
): Promise<ProviderResult> {
  const logger = options.logger ?? consoleLogger;
  let lastError: ProviderError | null = null;

  for (let attempt = 1; attempt <= options.retryPolicy.maxAttempts; attempt++) {
    const startedAt = Date.now();

    try {
      logger.info("Calling provider", {
        provider: provider.name,
        model: provider.model,
        attempt,
      });

      const result = await withTimeout(
        (signal) => provider.generate({ ...request, signal }),
        options.timeoutMs,
        request.signal
      );

      logger.info("Provider succeeded", {
        provider: provider.name,
        model: provider.model,
        attempt,
        latencyMs: Date.now() - startedAt,
      });

      return result;
    } catch (err) {
      const normalized = normalizeUnknownError(provider.name, err);
      lastError = normalized;

      logger.warn("Provider attempt failed", {
        provider: provider.name,
        model: provider.model,
        attempt,
        code: normalized.code,
        status: normalized.status,
        retryable: normalized.retryable,
        message: normalized.message,
        latencyMs: Date.now() - startedAt,
      });

      const shouldRetry =
        attempt < options.retryPolicy.maxAttempts &&
        isRetryableError(normalized);

      if (!shouldRetry) {
        break;
      }

      const delay = computeBackoffDelay(attempt, options.retryPolicy);
      await sleep(delay);
    }
  }

  throw lastError ?? new ProviderError({
    provider: provider.name,
    message: "Provider failed without explicit error",
    code: "UNKNOWN",
    retryable: false,
  });
}

export async function orchestrateAI(
  providers: AIProvider[],
  request: AIRequest,
  options: OrchestratorOptions
): Promise<OrchestrationResponse> {
  const logger = options.logger ?? consoleLogger;
  const attempts: AttemptFailure[] = [];

  if (providers.length === 0) {
    return {
      success: false,
      attempts,
      finalError: new ProviderError({
        provider: "orchestrator",
        message: "No providers configured",
        code: "BAD_REQUEST",
        retryable: false,
      }),
    };
  }

  for (const provider of providers) {
    try {
      const result = await executeWithRetry(provider, request, options);
      return {
        success: true,
        result,
        attempts,
      };
    } catch (err) {
      const normalized = normalizeUnknownError(provider.name, err);

      attempts.push({
        provider: provider.name,
        model: provider.model,
        error: {
          name: normalized.name,
          message: normalized.message,
          code: normalized.code,
          status: normalized.status,
          retryable: normalized.retryable,
        },
      });

      logger.warn("Provider failed, moving to fallback if available", {
        provider: provider.name,
        model: provider.model,
        code: normalized.code,
        retryable: normalized.retryable,
      });

      if (options.stopOnNonRetryableError && !normalized.retryable) {
        return {
          success: false,
          attempts,
          finalError: normalized,
        };
      }
    }
  }

  const finalError =
    attempts.length > 0
      ? new ProviderError({
          provider: attempts[attempts.length - 1].provider,
          message: "All providers failed",
          code: "UNAVAILABLE",
          retryable: true,
        })
      : new ProviderError({
          provider: "orchestrator",
          message: "Unknown orchestration failure",
          code: "UNKNOWN",
          retryable: false,
        });

  return {
    success: false,
    attempts,
    finalError,
  };
}
```

