      logger.info("Provider succeeded", {
        provider: provider.name,
        model: provider.model,
        attempt,
        latencyMs: Date.now() - startedAt,
      });

      return result;
    } catch (err) {
      const normalized = normalizeUnknownError(provider.name, err);
      lastError = normalized;

      logger.warn("Provider attempt failed", {
        provider: provider.name,
        model: provider.model,
        attempt,
        code: normalized.code,
        status: normalized.status,
        retryable: normalized.retryable,
        message: normalized.message,
        latencyMs: Date.now() - startedAt,
      });

      const shouldRetry =
        attempt < options.retryPolicy.maxAttempts &&
        isRetryableError(normalized);

      if (!shouldRetry) {
        break;
      }

      const delay = computeBackoffDelay(attempt, options.retryPolicy);
      await sleep(delay);
    }
  }

  throw lastError ?? new ProviderError({
    provider: provider.name,
    message: "Provider failed without explicit error",
    code: "UNKNOWN",
    retryable: false,
  });
