  return Math.max(min, Math.min(max, value));
}

function normalizeWhitespace(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

function wordCount(text: string): number {
  const normalized = normalizeWhitespace(text);
  if (!normalized) return 0;
  return normalized.split(" ").length;
}

function containsCodeBlock(text: string): boolean {
  return /```[\s\S]*?```/.test(text);
}

function looksLikeJson(text: string): boolean {
  const trimmed = text.trim();
  return (
    (trimmed.startsWith("{") && trimmed.endsWith("}")) ||
    (trimmed.startsWith("[") && trimmed.endsWith("]"))
  );
}

function isValidJson(text: string): boolean {
  try {
    JSON.parse(text);
    return true;
  } catch {
    return false;
  }
}

function containsRefusal(text: string): boolean {
  const lower = text.toLowerCase();
  const refusalPatterns = [
    "i can't help with that",
    "i cannot help with that",
    "i’m sorry, but i can’t",
    "i am sorry, but i can't",
    "i can't assist with that",
    "i cannot assist with that",
    "i must refuse",
    "i’m unable to comply",
    "i cannot comply",
  ];
  return refusalPatterns.some((p) => lower.includes(p));
}

function hasStructuredSections(text: string): boolean {
  return /(^|\n)(#+\s|\d+\.\s|- )/.test(text);
}

function keywordOverlapScore(prompt: string, response: string): number {
  const stopwords = new Set([
    "the", "a", "an", "is", "are", "to", "of", "and", "or", "in", "on", "for",
    "with", "that", "this", "it", "as", "be", "by", "at", "from", "how", "what",
    "why", "when", "which", "please", "can", "you", "i", "we"
  ]);

  const tokenize = (s: string) =>
    normalizeWhitespace(s.toLowerCase())
