## 3. provider 실행 orchestration 코드

실제 운영에서는 provider를 병렬 호출하고 timeout/failure를 안전하게 감싸는 계층이 필요합니다.

```ts
// orchestrator.ts

import {
  ProviderClient,
  ProviderRequest,
  ProviderResponse,
  WinnerResult,
  pickWinner,
  ScoreboardConfig,
} from "./scoreboard";

function withTimeout<T>(promise: Promise<T>, timeoutMs: number, errorMessage: string): Promise<T> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(errorMessage)), timeoutMs);

    promise
      .then((result) => {
        clearTimeout(timer);
        resolve(result);
      })
      .catch((err) => {
        clearTimeout(timer);
        reject(err);
      });
  });
}

async function safeExecute(client: ProviderClient, request: ProviderRequest): Promise<ProviderResponse> {
  const startedAt = Date.now();
  const timeoutMs = request.timeoutMs ?? 10_000;

  try {
    const response = await withTimeout(
      client.execute(request),
      timeoutMs,
      `${client.name} timed out after ${timeoutMs}ms`
    );

    return {
      ...response,
      provider: client.name,
      latencyMs: response.latencyMs || Date.now() - startedAt,
    };
  } catch (error) {
    return {
      provider: client.name,
      content: null,
      latencyMs: Date.now() - startedAt,
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
      confidence: 0,
      costUsd: 0,
    };
  }
}

export async function runScoreboardSelection(
  clients: ProviderClient[],
  request: ProviderRequest,
  config?: ScoreboardConfig
): Promise<WinnerResult> {
  const responses = await Promise.all(clients.map((client) => safeExecute(client, request)));
  return pickWinner(responses, config);
}
```

