    return response.content.trim().length > 0;
  },
};

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function scoreSuccess(response: ProviderResponse, weight: number): { score: number; reason: string } {
  if (response.success && response.content) {
    return { score: weight, reason: "Response succeeded" };
  }
  return { score: 0, reason: "Response failed or empty" };
}

function scoreLatency(
  response: ProviderResponse,
  weight: number,
  maxLatencyMs: number
): { score: number; reason: string } {
  if (!response.success) {
    return { score: 0, reason: "No latency score because response failed" };
  }

  const normalized = 1 - clamp(response.latencyMs / maxLatencyMs, 0, 1);
  const score = normalized * weight;
  return {
    score,
    reason: `Latency ${response.latencyMs}ms normalized to ${normalized.toFixed(2)}`,
  };
}

function scoreContentLength(
  response: ProviderResponse,
  weight: number,
  minLength: number,
  maxLength: number
): { score: number; reason: string } {
  if (!response.success || !response.content) {
    return { score: 0, reason: "No content length score because response failed" };
  }

  const length = response.content.trim().length;

  if (length < minLength) {
    const ratio = clamp(length / minLength, 0, 1);
    return {
      score: ratio * weight,
      reason: `Content too short (${length}), partial score`,
    };
  }

  if (length > maxLength) {
    const overflow = length - maxLength;
    const penaltyRatio = clamp(1 - overflow / maxLength, 0, 1);
    return {
      score: penaltyRatio * weight,
      reason: `Content too long (${length}), penalized`,
    };
  }

  return {
    score: weight,
    reason: `Content length ideal (${length})`,
  };
}

function scoreConfidence(response: ProviderResponse, weight: number): { score: number; reason: string } {
  if (!response.success) {
    return { score: 0, reason: "No confidence score because response failed" };
  }

  const confidence = clamp(response.confidence ?? 0.5, 0, 1);
  return {
    score: confidence * weight,
    reason: `Confidence ${confidence.toFixed(2)}`,
  };
}

function scoreCost(
  response: ProviderResponse,
  weight: number,
  maxCostUsd: number
): { score: number; reason: string } {
  if (!response.success) {
    return { score: 0, reason: "No cost score because response failed" };
  }

  const cost = response.costUsd ?? 0;
  const normalized = 1 - clamp(cost / maxCostUsd, 0, 1);
  return {
    score: normalized * weight,
    reason: `Cost $${cost.toFixed(4)} normalized to ${normalized.toFixed(2)}`,
  };
}

function scoreValidation(
  response: ProviderResponse,
  weight: number,
  validator?: (response: ProviderResponse) => boolean
): { score: number; reason: string } {
  if (!validator) {
    return { score: weight, reason: "No validator configured, full score granted" };
  }

  const valid = validator(response);
  return {
    score: valid ? weight : 0,
    reason: valid ? "Validation passed" : "Validation failed",
  };
}

export function evaluateResponse(
  response: ProviderResponse,
  config: ScoreboardConfig = defaultConfig
): ScoreBreakdown {
  const success = scoreSuccess(response, config.weights.success);
  const latency = scoreLatency(response, config.weights.latency, config.maxLatencyMs);
  const contentLength = scoreContentLength(
    response,
    config.weights.contentLength,
    config.idealContentLength.min,
    config.idealContentLength.max
  );
  const confidence = scoreConfidence(response, config.weights.confidence);
  const cost = scoreCost(response, config.weights.cost, config.maxCostUsd);
  const validation = scoreValidation(response, config.weights.validation, config.validator);

  const totalScore =
    success.score +
    latency.score +
    contentLength.score +
    confidence.score +
    cost.score +
    validation.score;

  return {
    provider: response.provider,
    totalScore,
    scores: {
      success: success.score,
      latency: latency.score,
      contentLength: contentLength.score,
      confidence: confidence.score,
      cost: cost.score,
      validation: validation.score,
    },
    reasons: [
      success.reason,
      latency.reason,
      contentLength.reason,
      confidence.reason,
      cost.reason,
      validation.reason,
    ],
    response,
  };
}

export function pickWinner(
  responses: ProviderResponse[],
  config: ScoreboardConfig = defaultConfig
): WinnerResult {
  const rankings = responses
    .map((response) => evaluateResponse(response, config))
    .sort((a, b) => {
      if (b.totalScore !== a.totalScore) {
        return b.totalScore - a.totalScore;
      }

      // tie-breaker 1: validation score
      if (b.scores.validation !== a.scores.validation) {
        return b.scores.validation - a.scores.validation;
      }

      // tie-breaker 2: success score
      if (b.scores.success !== a.scores.success) {
        return b.scores.success - a.scores.success;
      }

      // tie-breaker 3: lower latency wins
      return a.response.latencyMs - b.response.latencyMs;
    });

  return {
    winner: rankings[0] ?? null,
    rankings,
  };
}
