# 4) 타입 정의: `src/types.ts`

오케스트레이션의 핵심 상태와 인터페이스를 정의합니다.

```ts
export type WorkflowStatus =
  | "PENDING"
  | "PLANNING"
  | "EXECUTING"
  | "JUDGING"
  | "SUCCEEDED"
  | "FAILED";

export interface WorkflowInput {
  requestId: string;
  goal: string;
  maxAttempts?: number;
}

export interface PlanStep {
  id: string;
  description: string;
}

export interface Plan {
  steps: PlanStep[];
  strategySummary: string;
}

export interface ExecutionStepResult {
  stepId: string;
  success: boolean;
  output: string;
  error?: string;
  startedAt: string;
  finishedAt: string;
}

export interface ExecutionResult {
  success: boolean;
  stepResults: ExecutionStepResult[];
  summary: string;
}

export interface JudgeResult {
  approved: boolean;
  score: number; // 0~100
  reasons: string[];
  shouldRetry: boolean;
}

export interface WorkflowState {
  requestId: string;
  goal: string;
  status: WorkflowStatus;
  attempt: number;
  maxAttempts: number;

  plan?: Plan;
  executionResult?: ExecutionResult;
  judgeResult?: JudgeResult;

  error?: string;
  createdAt: string;
  updatedAt: string;
}

export interface Planner {
  createPlan(input: WorkflowInput, state: WorkflowState): Promise<Plan>;
}

export interface Executor {
  execute(plan: Plan, state: WorkflowState): Promise<ExecutionResult>;
}

export interface Judge {
  evaluate(
    input: WorkflowInput,
    state: WorkflowState,
    plan: Plan,
    executionResult: ExecutionResult
  ): Promise<JudgeResult>;
}
```

