# 6) Planner 구현: `src/planner.ts`

여기서는 goal을 바탕으로 단순한 plan을 만듭니다.
실무에서는 이 부분이 LLM 호출, 규칙 엔진, 템플릿 기반 planning으로 바뀔 수 있습니다.

```ts
import { Plan, Planner, WorkflowInput, WorkflowState } from "./types";

export class SimplePlanner implements Planner {
  async createPlan(input: WorkflowInput, _state: WorkflowState): Promise<Plan> {
    const normalizedGoal = input.goal.trim();

    const steps = [
      {
        id: "analyze-goal",
        description: `Analyze goal: ${normalizedGoal}`
      },
      {
        id: "perform-work",
        description: `Perform work required for goal: ${normalizedGoal}`
      },
      {
        id: "summarize-result",
        description: "Summarize the execution result"
      }
    ];

    return {
      steps,
      strategySummary: `Three-step strategy for goal "${normalizedGoal}"`
    };
  }
}
```

