# 7) Executor 구현: `src/executor.ts`

각 step을 순차 실행합니다.
실무에서는:
- 외부 API 호출
- shell/job 실행
- DB 작업
- 병렬 step 처리
등으로 확장 가능합니다.

```ts
import {
  ExecutionResult,
  ExecutionStepResult,
  Executor,
  Plan,
  PlanStep,
  WorkflowState
} from "./types";

function nowIso(): string {
  return new Date().toISOString();
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export class SimpleExecutor implements Executor {
  async execute(plan: Plan, _state: WorkflowState): Promise<ExecutionResult> {
    const stepResults: ExecutionStepResult[] = [];

    for (const step of plan.steps) {
      const result = await this.executeStep(step);
      stepResults.push(result);

      if (!result.success) {
        return {
          success: false,
          stepResults,
          summary: `Execution failed at step "${step.id}"`
        };
      }
    }

    return {
      success: true,
      stepResults,
      summary: "All plan steps executed successfully"
    };
  }

  private async executeStep(step: PlanStep): Promise<ExecutionStepResult> {
    const startedAt = nowIso();

    try {
      await sleep(200);

      // 예시용 실패 조건:
      // step description에 "fail"이 포함되면 실패 처리
      const shouldFail = step.description.toLowerCase().includes("fail");

      if (shouldFail) {
        throw new Error(`Simulated failure for step "${step.id}"`);
      }

      return {
        stepId: step.id,
        success: true,
        output: `Completed: ${step.description}`,
        startedAt,
        finishedAt: nowIso()
      };
    } catch (error) {
      return {
        stepId: step.id,
        success: false,
        output: "",
        error: error instanceof Error ? error.message : "Unknown execution error",
        startedAt,
        finishedAt: nowIso()
      };
    }
  }
}
```

