# 8) Judge 구현: `src/judge.ts`

judge는 실행 결과를 평가하고 승인/재시도 여부를 결정합니다.

```ts
import {
  ExecutionResult,
  Judge,
  JudgeResult,
  Plan,
  WorkflowInput,
  WorkflowState
} from "./types";

export class SimpleJudge implements Judge {
  async evaluate(
    _input: WorkflowInput,
    state: WorkflowState,
    _plan: Plan,
    executionResult: ExecutionResult
  ): Promise<JudgeResult> {
    const reasons: string[] = [];

    if (!executionResult.success) {
      reasons.push("Execution result indicates failure");
      return {
        approved: false,
        score: 20,
        reasons,
        shouldRetry: state.attempt < state.maxAttempts
      };
    }

    const successfulSteps = executionResult.stepResults.filter((s) => s.success).length;
    const totalSteps = executionResult.stepResults.length;
    const score = totalSteps === 0 ? 0 : Math.round((successfulSteps / totalSteps) * 100);

    if (score >= 100) {
      reasons.push("All steps completed successfully");
      return {
        approved: true,
        score,
        reasons,
        shouldRetry: false
      };
    }

    reasons.push("Not all steps completed successfully");
    return {
      approved: false,
      score,
      reasons,
      shouldRetry: state.attempt < state.maxAttempts
    };
  }
}
```

