# 4) Provider Router 구현

`src/providers/provider.router.ts`

```ts
import {
  Channel,
  MessageProvider,
  SendMessageInput,
  SendMessageResult,
} from './provider.types';

export class ProviderRouter {
  constructor(private readonly providers: MessageProvider[]) {}

  getProvider(channel: Channel): MessageProvider {
    const provider = this.providers.find((p) => p.supports(channel));

    if (!provider) {
      throw new Error(`No provider found for channel: ${channel}`);
    }

    return provider;
  }

  async send(input: SendMessageInput): Promise<SendMessageResult> {
    const provider = this.getProvider(input.channel);
    return provider.send(input);
  }
}
```

