# 6) 실행 코드

`src/index.ts`

```ts
import { EmailProvider } from './providers/email.provider';
import { SmsProvider } from './providers/sms.provider';
import { PushProvider } from './providers/push.provider';
import { ProviderRouter } from './providers/provider.router';
import { NotificationService } from './services/notification.service';

async function main() {
  const providers = [
    new EmailProvider(),
    new SmsProvider(),
    new PushProvider(),
  ];

  const providerRouter = new ProviderRouter(providers);
  const notificationService = new NotificationService(providerRouter);

  const emailResult = await notificationService.sendMessage({
    channel: 'email',
    to: 'user@example.com',
    subject: 'Hello',
    content: 'Welcome!',
  });

  console.log('emailResult:', emailResult);

  const smsResult = await notificationService.sendMessage({
    channel: 'sms',
    to: '01012345678',
    content: '인증번호는 123456 입니다.',
  });

  console.log('smsResult:', smsResult);

  const pushResult = await notificationService.sendMessage({
    channel: 'push',
    to: 'device-token-123',
    content: '새 알림이 도착했습니다.',
  });

  console.log('pushResult:', pushResult);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
