### Fallback Router

`src/providers/provider.router.ts`

```ts
import {
  Channel,
  MessageProvider,
  SendMessageInput,
  SendMessageResult,
} from './provider.types';

export class ProviderRouter {
  constructor(private readonly providers: MessageProvider[]) {}

  getProviders(channel: Channel): MessageProvider[] {
    return this.providers
      .filter((p) => p.supports(channel))
      .sort((a, b) => a.priority - b.priority);
  }

  async send(input: SendMessageInput): Promise<SendMessageResult> {
    const providers = this.getProviders(input.channel);

    if (providers.length === 0) {
      throw new Error(`No provider found for channel: ${input.channel}`);
    }

    const errors: string[] = [];

    for (const provider of providers) {
      try {
        const result = await provider.send(input);
        if (result.success) {
          return result;
        }

        errors.push(`${provider.name}: ${result.error ?? 'unknown error'}`);
      } catch (error) {
        const message =
          error instanceof Error ? error.message : 'unknown exception';
        errors.push(`${provider.name}: ${message}`);
      }
    }

    return {
      success: false,
      provider: 'provider-router',
      error: `All providers failed. ${errors.join(', ')}`,
    };
  }
}
```

