## 2) 전체 코드 예시

### `ai-orchestrator.ts`

```ts
/* eslint-disable no-console */

export type AIMessage = {
  role: "system" | "user" | "assistant";
  content: string;
};

export type AIRequest = {
  messages: AIMessage[];
  temperature?: number;
  maxTokens?: number;
  signal?: AbortSignal;
  metadata?: Record<string, unknown>;
};

export type AIResponse = {
  provider: string;
  model: string;
  content: string;
  usage?: {
    inputTokens?: number;
    outputTokens?: number;
    totalTokens?: number;
  };
  latencyMs: number;
  finishReason?: string;
};

export class AIProviderError extends Error {
  public readonly provider: string;
  public readonly code: string;
  public readonly retryable: boolean;
  public readonly cause?: unknown;
  public readonly status?: number;

  constructor(params: {
    provider: string;
    message: string;
    code: string;
    retryable: boolean;
    cause?: unknown;
    status?: number;
  }) {
    super(params.message);
    this.name = "AIProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.retryable = params.retryable;
    this.cause = params.cause;
    this.status = params.status;
  }
}

export class AllProvidersFailedError extends Error {
  public readonly errors: AIProviderError[];

  constructor(errors: AIProviderError[]) {
    super(
      `All providers failed: ${errors
        .map((e) => `${e.provider}(${e.code})`)
        .join(", ")}`
    );
    this.name = "AllProvidersFailedError";
    this.errors = errors;
  }
}

export interface AIProvider {
  name: string;
  model: string;
  generate(request: AIRequest): Promise<AIResponse>;
}

export type Logger = {
  info?: (message: string, meta?: Record<string, unknown>) => void;
  warn?: (message: string, meta?: Record<string, unknown>) => void;
  error?: (message: string, meta?: Record<string, unknown>) => void;
  debug?: (message: string, meta?: Record<string, unknown>) => void;
};

export type RetryPolicy = {
  maxAttempts: number; // 1이면 재시도 없음
  backoffMs: (attempt: number) => number;
  shouldRetry?: (error: AIProviderError) => boolean;
};

export type OrchestratorOptions = {
  providers: AIProvider[];
  logger?: Logger;
  retryPolicy?: RetryPolicy;
  perProviderTimeoutMs?: number;
  continueOnAbort?: boolean;
};

function defaultShouldRetry(error: AIProviderError): boolean {
  return error.retryable;
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      resolve();
    }, ms);

    const onAbort = () => {
      clearTimeout(timer);
      cleanup();
      reject(
        new AIProviderError({
          provider: "orchestrator",
          message: "Sleep aborted",
          code: "ABORTED",
          retryable: false,
        })
      );
    };

    const cleanup = () => {
      if (signal) {
        signal.removeEventListener("abort", onAbort);
      }
    };

    if (signal) {
      if (signal.aborted) {
        onAbort();
        return;
      }
      signal.addEventListener("abort", onAbort, { once: true });
    }
  });
}

function withTimeoutSignal(
  parentSignal: AbortSignal | undefined,
  timeoutMs: number
): { signal: AbortSignal; cleanup: () => void } {
  const controller = new AbortController();

  const timeout = setTimeout(() => {
    controller.abort(new Error(`Timed out after ${timeoutMs}ms`));
  }, timeoutMs);

  const onParentAbort = () => {
    controller.abort(parentSignal?.reason ?? new Error("Parent aborted"));
  };

  if (parentSignal) {
    if (parentSignal.aborted) {
      controller.abort(parentSignal.reason ?? new Error("Parent aborted"));
    } else {
      parentSignal.addEventListener("abort", onParentAbort, { once: true });
    }
  }

  return {
    signal: controller.signal,
    cleanup: () => {
      clearTimeout(timeout);
      if (parentSignal) {
        parentSignal.removeEventListener("abort", onParentAbort);
      }
    },
  };
}

function normalizeProviderError(
  provider: string,
  err: unknown
): AIProviderError {
  if (err instanceof AIProviderError) {
    return err;
  }

  if (err instanceof Error) {
    const message = err.message.toLowerCase();

    if (message.includes("timeout") || message.includes("timed out")) {
      return new AIProviderError({
        provider,
        message: err.message,
        code: "TIMEOUT",
        retryable: true,
        cause: err,
      });
    }

    if (message.includes("abort")) {
      return new AIProviderError({
        provider,
        message: err.message,
        code: "ABORTED",
        retryable: false,
        cause: err,
      });
    }

    return new AIProviderError({
      provider,
      message: err.message,
      code: "UNKNOWN",
      retryable: false,
      cause: err,
    });
  }

  return new AIProviderError({
    provider,
    message: "Non-error thrown",
    code: "UNKNOWN",
    retryable: false,
    cause: err,
  });
}

async function executeWithRetry(
  provider: AIProvider,
  request: AIRequest,
  retryPolicy: RetryPolicy,
  logger?: Logger,
  perProviderTimeoutMs?: number
): Promise<AIResponse> {
  let lastError: AIProviderError | undefined;

  for (let attempt = 1; attempt <= retryPolicy.maxAttempts; attempt++) {
    const startedAt = Date.now();
    let cleanup: (() => void) | undefined;

    try {
      const effectiveRequest: AIRequest = { ...request };

      if (perProviderTimeoutMs && perProviderTimeoutMs > 0) {
        const wrapped = withTimeoutSignal(request.signal, perProviderTimeoutMs);
        effectiveRequest.signal = wrapped.signal;
        cleanup = wrapped.cleanup;
      }

      logger?.info?.("Calling AI provider", {
        provider: provider.name,
        model: provider.model,
        attempt,
      });

      const result = await provider.generate(effectiveRequest);

      logger?.info?.("AI provider succeeded", {
        provider: provider.name,
        model: provider.model,
        attempt,
        latencyMs: Date.now() - startedAt,
      });

      return result;
    } catch (err) {
      const normalized = normalizeProviderError(provider.name, err);
      lastError = normalized;

      logger?.warn?.("AI provider attempt failed", {
        provider: provider.name,
        model: provider.model,
        attempt,
        code: normalized.code,
        retryable: normalized.retryable,
        message: normalized.message,
        status: normalized.status,
        latencyMs: Date.now() - startedAt,
      });

      const shouldRetry =
        attempt < retryPolicy.maxAttempts &&
        (retryPolicy.shouldRetry ?? defaultShouldRetry)(normalized);

      if (!shouldRetry) {
        throw normalized;
      }

      const backoff = retryPolicy.backoffMs(attempt);

      logger?.debug?.("Retrying AI provider", {
        provider: provider.name,
        attempt,
        nextAttempt: attempt + 1,
        backoffMs: backoff,
      });

      await sleep(backoff, request.signal);
    } finally {
      cleanup?.();
    }
  }

  throw (
    lastError ??
    new AIProviderError({
      provider: provider.name,
      message: "Unknown provider failure",
      code: "UNKNOWN",
      retryable: false,
    })
  );
}

export class AIOrchestrator {
  private readonly providers: AIProvider[];
  private readonly logger?: Logger;
  private readonly retryPolicy: RetryPolicy;
  private readonly perProviderTimeoutMs?: number;
  private readonly continueOnAbort: boolean;

  constructor(options: OrchestratorOptions) {
    if (!options.providers.length) {
      throw new Error("At least one provider is required");
    }

    this.providers = options.providers;
    this.logger = options.logger;
    this.retryPolicy = options.retryPolicy ?? {
      maxAttempts: 2,
      backoffMs: (attempt) => Math.min(300 * 2 ** (attempt - 1), 2000),
      shouldRetry: (error) => error.retryable,
    };
    this.perProviderTimeoutMs = options.perProviderTimeoutMs ?? 15_000;
    this.continueOnAbort = options.continueOnAbort ?? false;
  }

  async generate(request: AIRequest): Promise<AIResponse> {
    const errors: AIProviderError[] = [];

    for (const provider of this.providers) {
      if (request.signal?.aborted && !this.continueOnAbort) {
        throw new AIProviderError({
          provider: "orchestrator",
          message: "Request aborted before provider execution",
          code: "ABORTED",
          retryable: false,
          cause: request.signal.reason,
        });
      }

      try {
        const result = await executeWithRetry(
          provider,
          request,
          this.retryPolicy,
          this.logger,
          this.perProviderTimeoutMs
        );

        return result;
      } catch (err) {
        const normalized = normalizeProviderError(provider.name, err);
        errors.push(normalized);

        this.logger?.warn?.("Provider failed, falling back to next provider", {
          provider: provider.name,
          model: provider.model,
          code: normalized.code,
          message: normalized.message,
        });

        if (normalized.code === "ABORTED" && !this.continueOnAbort) {
          throw normalized;
        }
      }
    }

    this.logger?.error?.("All AI providers failed", {
      errors: errors.map((e) => ({
        provider: e.provider,
        code: e.code,
        message: e.message,
        retryable: e.retryable,
        status: e.status,
      })),
    });

    throw new AllProvidersFailedError(errors);
  }
}
```

