## 2) Zod 스키마 검증

LLM 출력은 반드시 검증하는 것이 좋습니다.

```ts
// judge/schema.ts
import { z } from "zod";

export const scoreBreakdownSchema = z.object({
  correctness: z.number().min(1).max(10),
  relevance: z.number().min(1).max(10),
  clarity: z.number().min(1).max(10),
  completeness: z.number().min(1).max(10),
  safety: z.number().min(1).max(10),
});

export const judgeResponseSchema = z.object({
  winner: z.enum(["response_a", "response_b", "tie"]),
  confidence: z.number().min(0).max(1),
  reasoning: z.string().min(1).max(2000),
  scores: z.object({
    response_a: scoreBreakdownSchema,
    response_b: scoreBreakdownSchema,
  }),
});

export type JudgeLLMResponse = z.infer<typeof judgeResponseSchema>;
```

