// judge/openaiJudgeClient.ts
import OpenAI from "openai";
import { JudgeModelClient } from "./client";

export class OpenAIJudgeClient implements JudgeModelClient {
  constructor(
    private readonly openai: OpenAI,
    private readonly model: string = "gpt-4.1"
