## 6) 핵심 judge 함수

여기서 실제 비교를 수행합니다.

```ts
// judge/judgeResponses.ts
import { JudgeModelClient } from "./client";
import { buildJudgePrompt } from "./prompt";
import { extractJsonObject } from "./parse";
import { judgeResponseSchema } from "./schema";
import { CandidateModel, JudgeInput, JudgeResult } from "./types";

function randomizeOrder(input: JudgeInput): {
  responseA: string;
  responseB: string;
  mapBack: Record<"response_a" | "response_b", CandidateModel>;
} {
  const flip = Math.random() < 0.5;

  if (flip) {
    return {
      responseA: input.openaiResponse,
      responseB: input.claudeResponse,
      mapBack: {
        response_a: "openai",
        response_b: "claude",
      },
    };
  }

  return {
    responseA: input.claudeResponse,
    responseB: input.openaiResponse,
    mapBack: {
      response_a: "claude",
      response_b: "openai",
    },
  };
}

function remapWinner(
  winner: "response_a" | "response_b" | "tie",
  mapBack: Record<"response_a" | "response_b", CandidateModel>
): "openai" | "claude" | "tie" {
  if (winner === "tie") return "tie";
  return mapBack[winner];
}

function remapScores(
  parsed: {
    scores: {
      response_a: any;
      response_b: any;
    };
  },
  mapBack: Record<"response_a" | "response_b", CandidateModel>
) {
  const openaiKey =
    mapBack.response_a === "openai" ? "response_a" : "response_b";
  const claudeKey =
    mapBack.response_a === "claude" ? "response_a" : "response_b";

  return {
    openai: parsed.scores[openaiKey],
    claude: parsed.scores[claudeKey],
  };
}

function fallbackHeuristic(rawJudgeResponse?: string): JudgeResult {
  return {
    winner: "tie",
    confidence: 0.1,
    reasoning:
      "Judge output could not be parsed reliably, so a tie fallback was returned.",
    scores: {
      openai: {
        correctness: 5,
        relevance: 5,
        clarity: 5,
        completeness: 5,
        safety: 5,
      },
      claude: {
        correctness: 5,
        relevance: 5,
        clarity: 5,
        completeness: 5,
        safety: 5,
      },
    },
    rawJudgeResponse,
  };
}

export async function judgeResponses(
  client: JudgeModelClient,
  input: JudgeInput
): Promise<JudgeResult> {
  const { responseA, responseB, mapBack } = randomizeOrder(input);

  const prompt = buildJudgePrompt({
    userPrompt: input.userPrompt,
    responseA,
    responseB,
  });

  let raw = "";

  try {
    raw = await client.complete(prompt);

    const jsonText = extractJsonObject(raw);
    const parsedJson = JSON.parse(jsonText);
    const parsed = judgeResponseSchema.parse(parsedJson);

    return {
      winner: remapWinner(parsed.winner, mapBack),
      confidence: parsed.confidence,
      reasoning: parsed.reasoning,
      scores: remapScores(parsed, mapBack),
      rawJudgeResponse: raw,
    };
  } catch {
    return fallbackHeuristic(raw);
  }
}
```

