# Judge 클라이언트 인터페이스

judge 모델이 OpenAI일 수도 있고, 다른 모델일 수도 있으므로 추상화합니다.

```ts
// judge/client.ts
export interface JudgeModelClient {
  complete(prompt: string): Promise<string>;
}
```

예를 들어 OpenAI SDK를 감싼 구현:

```ts
// judge/openaiJudgeClient.ts
import OpenAI from "openai";
import { JudgeModelClient } from "./client";

export class OpenAIJudgeClient implements JudgeModelClient {
  constructor(
    private readonly openai: OpenAI,
    private readonly model: string = "gpt-4.1"
  ) {}

  async complete(prompt: string): Promise<string> {
    const response = await this.openai.responses.create({
      model: this.model,
      input: [
        {
          role: "system",
          content: "You are a strict JSON-only evaluation engine.",
        },
        {
          role: "user",
          content: prompt,
        },
      ],
      temperature: 0,
    });

    // SDK 버전에 따라 output_text 접근 방식이 다를 수 있어 방어적으로 처리
    const text =
      response.output_text ??
      response.output
        ?.flatMap((item: any) => item.content ?? [])
        ?.map((c: any) => c.text ?? "")
        ?.join("") ??
      "";

    return text.trim();
  }
}
```

