## `scoreboard.ts`

```ts
export type ProviderName = string;

export interface ProviderRequest {
  prompt: string;
  metadata?: Record<string, unknown>;
}

export interface ProviderRawResponse {
  provider: ProviderName;
  content: string | null;
  latencyMs: number;
  success: boolean;
  statusCode?: number;
  error?: string;
  metadata?: Record<string, unknown>;
}

export interface ScoreBreakdown {
  availability: number;
  latency: number;
  contentLength: number;
  jsonValidity: number;
  safetyPenalty: number;
  customQuality: number;
  total: number;
  reasons: string[];
}

export interface ScoredProviderResponse {
  response: ProviderRawResponse;
  score: ScoreBreakdown;
}

export interface WinnerResult {
  winner: ScoredProviderResponse | null;
  ranked: ScoredProviderResponse[];
  tie: boolean;
  decisionReason: string;
}

export interface ScoreboardConfig {
  weights: {
    availability: number;
    latency: number;
    contentLength: number;
    jsonValidity: number;
    safetyPenalty: number;
    customQuality: number;
  };
  latency: {
    excellentMs: number;
    goodMs: number;
    acceptableMs: number;
    maxScore: number;
    minScore: number;
  };
  contentLength: {
    minUsefulChars: number;
    idealChars: number;
    maxScore: number;
    minScore: number;
  };
  jsonValidity: {
    enabled: boolean;
    maxScore: number;
    minScore: number;
  };
  safety: {
    bannedPatterns: RegExp[];
    penaltyPerMatch: number;
    minScore: number;
  };
  tieBreaker: "latency" | "contentLength" | "providerName";
}

export interface Provider {
  name: ProviderName;
  generate(request: ProviderRequest): Promise<ProviderRawResponse>;
}

export const defaultScoreboardConfig: ScoreboardConfig = {
  weights: {
    availability: 0.35,
    latency: 0.2,
    contentLength: 0.15,
    jsonValidity: 0.1,
    safetyPenalty: 0.1,
    customQuality: 0.1,
  },
  latency: {
    excellentMs: 500,
    goodMs: 1200,
    acceptableMs: 2500,
    maxScore: 100,
    minScore: 0,
  },
  contentLength: {
    minUsefulChars: 40,
    idealChars: 300,
    maxScore: 100,
    minScore: 0,
  },
  jsonValidity: {
    enabled: false,
    maxScore: 100,
    minScore: 0,
  },
  safety: {
    bannedPatterns: [
      /internal server error/i,
      /stack trace/i,
      /exception:/i,
      /undefined/i,
      /null reference/i,
    ],
    penaltyPerMatch: 25,
    minScore: 0,
  },
  tieBreaker: "latency",
};

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function scoreAvailability(response: ProviderRawResponse): { score: number; reasons: string[] } {
  const reasons: string[] = [];

  if (!response.success) {
    reasons.push("Provider response marked as unsuccessful");
    return { score: 0, reasons };
  }

  if (!response.content || response.content.trim().length === 0) {
    reasons.push("Empty content");
    return { score: 10, reasons };
  }

  reasons.push("Successful non-empty response");
  return { score: 100, reasons };
}

function scoreLatency(
  response: ProviderRawResponse,
  config: ScoreboardConfig
): { score: number; reasons: string[] } {
  const { excellentMs, goodMs, acceptableMs, maxScore, minScore } = config.latency;
  const reasons: string[] = [];
  const latency = response.latencyMs;

  let score: number;

  if (latency <= excellentMs) {
    score = maxScore;
    reasons.push(`Excellent latency: ${latency}ms`);
  } else if (latency <= goodMs) {
    const ratio = (latency - excellentMs) / (goodMs - excellentMs);
    score = maxScore - ratio * 20;
    reasons.push(`Good latency: ${latency}ms`);
  } else if (latency <= acceptableMs) {
    const ratio = (latency - goodMs) / (acceptableMs - goodMs);
    score = 80 - ratio * 40;
    reasons.push(`Acceptable latency: ${latency}ms`);
  } else {
    score = 20;
    reasons.push(`Slow latency: ${latency}ms`);
  }

  return { score: clamp(score, minScore, maxScore), reasons };
}

function scoreContentLength(
  response: ProviderRawResponse,
  config: ScoreboardConfig
): { score: number; reasons: string[] } {
  const reasons: string[] = [];
  const content = response.content?.trim() ?? "";
  const len = content.length;
  const { minUsefulChars, idealChars, maxScore, minScore } = config.contentLength;

  if (len === 0) {
    reasons.push("No content");
    return { score: minScore, reasons };
  }

  if (len < minUsefulChars) {
    const score = (len / minUsefulChars) * 50;
    reasons.push(`Too short: ${len} chars`);
    return { score: clamp(score, minScore, maxScore), reasons };
  }

  if (len <= idealChars) {
    const ratio = (len - minUsefulChars) / Math.max(1, idealChars - minUsefulChars);
    const score = 50 + ratio * 50;
    reasons.push(`Useful content length: ${len} chars`);
    return { score: clamp(score, minScore, maxScore), reasons };
  }

  const overflow = len - idealChars;
  const penalty = Math.min(30, overflow / 50);
  const score = maxScore - penalty;
  reasons.push(`Long content: ${len} chars`);
  return { score: clamp(score, minScore, maxScore), reasons };
}

function scoreJsonValidity(
  response: ProviderRawResponse,
  config: ScoreboardConfig
): { score: number; reasons: string[] } {
  const reasons: string[] = [];

  if (!config.jsonValidity.enabled) {
    reasons.push("JSON validity scoring disabled");
    return { score: 100, reasons };
  }

  const content = response.content?.trim();
  if (!content) {
    reasons.push("No content for JSON validation");
    return { score: config.jsonValidity.minScore, reasons };
  }

  try {
    JSON.parse(content);
    reasons.push("Valid JSON");
    return { score: config.jsonValidity.maxScore, reasons };
  } catch {
    reasons.push("Invalid JSON");
    return { score: config.jsonValidity.minScore, reasons };
  }
}

function scoreSafetyPenalty(
  response: ProviderRawResponse,
  config: ScoreboardConfig
): { score: number; reasons: string[] } {
  const reasons: string[] = [];
  const content = response.content ?? "";

  let penalty = 0;
  for (const pattern of config.safety.bannedPatterns) {
    if (pattern.test(content)) {
      penalty += config.safety.penaltyPerMatch;
      reasons.push(`Matched banned pattern: ${pattern}`);
    }
  }

  const score = clamp(100 - penalty, config.safety.minScore, 100);
  if (reasons.length === 0) {
    reasons.push("No banned patterns detected");
  }

  return { score, reasons };
}

function scoreCustomQuality(response: ProviderRawResponse): { score: number; reasons: string[] } {
  const reasons: string[] = [];
  const content = response.content?.trim() ?? "";

  if (!content) {
    reasons.push("No content");
    return { score: 0, reasons };
  }

  let score = 50;

  const sentenceCount = content
    .split(/[.!?]\s+/)
    .map((s) => s.trim())
    .filter(Boolean).length;

  if (sentenceCount >= 2) {
    score += 20;
    reasons.push(`Contains multiple sentences: ${sentenceCount}`);
  } else {
    reasons.push("Single sentence or fragmented response");
  }

  const uniqueWords = new Set(
    content
      .toLowerCase()
      .split(/\s+/)
      .map((w) => w.replace(/[^\w가-힣]/g, ""))
      .filter(Boolean)
  );

  const totalWords = content.split(/\s+/).filter(Boolean).length;
  const lexicalDiversity = totalWords > 0 ? uniqueWords.size / totalWords : 0;

  if (lexicalDiversity > 0.6) {
    score += 20;
    reasons.push(`Good lexical diversity: ${lexicalDiversity.toFixed(2)}`);
  } else if (lexicalDiversity < 0.3) {
    score -= 20;
    reasons.push(`Low lexical diversity: ${lexicalDiversity.toFixed(2)}`);
  } else {
    reasons.push(`Moderate lexical diversity: ${lexicalDiversity.toFixed(2)}`);
  }

  if (/sorry|cannot|can't|unable/i.test(content)) {
    score -= 10;
    reasons.push("Contains refusal/limitation phrasing");
  }

  return { score: clamp(score, 0, 100), reasons };
}

export function scoreResponse(
  response: ProviderRawResponse,
  config: ScoreboardConfig = defaultScoreboardConfig
): ScoredProviderResponse {
  const availability = scoreAvailability(response);
  const latency = scoreLatency(response, config);
  const contentLength = scoreContentLength(response, config);
  const jsonValidity = scoreJsonValidity(response, config);
  const safetyPenalty = scoreSafetyPenalty(response, config);
  const customQuality = scoreCustomQuality(response);

