  if (!config.jsonValidity.enabled) {
    reasons.push("JSON validity scoring disabled");
    return { score: 100, reasons };
  }

  const content = response.content?.trim();
  if (!content) {
    reasons.push("No content for JSON validation");
    return { score: config.jsonValidity.minScore, reasons };
  }

  try {
    JSON.parse(content);
    reasons.push("Valid JSON");
    return { score: config.jsonValidity.maxScore, reasons };
  } catch {
    reasons.push("Invalid JSON");
    return { score: config.jsonValidity.minScore, reasons };
  }
}

function scoreSafetyPenalty(
  response: ProviderRawResponse,
  config: ScoreboardConfig
): { score: number; reasons: string[] } {
  const reasons: string[] = [];
  const content = response.content ?? "";

  let penalty = 0;
  for (const pattern of config.safety.bannedPatterns) {
    if (pattern.test(content)) {
      penalty += config.safety.penaltyPerMatch;
      reasons.push(`Matched banned pattern: ${pattern}`);
    }
  }

  const score = clamp(100 - penalty, config.safety.minScore, 100);
  if (reasons.length === 0) {
    reasons.push("No banned patterns detected");
  }

  return { score, reasons };
}

