```ts
import { Plan, Planner, PlanStep, UserRequest } from "./types.js";

export class SimplePlanner implements Planner {
  async createPlan(request: UserRequest): Promise<Plan> {
    const goal = request.goal.toLowerCase();
    const steps: PlanStep[] = [];

    // 항상 먼저 파싱
    steps.push({
      id: "step-parse",
      description: "Parse input text into normalized tokens and metadata",
      action: "PARSE_TEXT"
    });

    if (goal.includes("word") || goal.includes("단어")) {
      steps.push({
        id: "step-count-words",
        description: "Count words from the input text",
        action: "COUNT_WORDS"
      });
    }

    if (
      goal.includes("sum") ||
      goal.includes("합") ||
      goal.includes("number") ||
      goal.includes("숫자")
    ) {
      steps.push({
        id: "step-sum-numbers",
        description: "Extract and sum all numbers from the input text",
        action: "SUM_NUMBERS"
      });
    }

    // goal이 애매하면 기본 분석으로 word count 추가
    if (steps.length === 1) {
      steps.push({
        id: "step-count-words",
        description: "Default analysis: count words",
        action: "COUNT_WORDS"
      });
    }

    return {
      steps,
      rationale: `Plan created from goal="${request.goal}".`
    };
  }
}
```

