# 6) `src/judge.ts`

judge는 execution 결과가 요청 의도에 맞는지 검증합니다.

```ts
import {
  ExecutionResult,
  Judge,
  Judgment,
  Plan,
  UserRequest
} from "./types.js";

export class SimpleJudge implements Judge {
  async evaluate(
    request: UserRequest,
    plan: Plan,
    execution: ExecutionResult
  ): Promise<Judgment> {
    const reasons: string[] = [];
    let score = 100;
    const goal = request.goal.toLowerCase();

    if (!execution.success) {
      reasons.push("Execution failed.");
      score -= 60;
    }

    if (plan.steps.length === 0) {
      reasons.push("Plan contains no steps.");
      score -= 40;
    }

    if (
      (goal.includes("word") || goal.includes("단어")) &&
      execution.finalOutput.wordCount === undefined
    ) {
      reasons.push("Expected wordCount in final output, but it was missing.");
      score -= 25;
    }

    if (
      (goal.includes("sum") ||
        goal.includes("합") ||
        goal.includes("number") ||
        goal.includes("숫자")) &&
      execution.finalOutput.sum === undefined
    ) {
      reasons.push("Expected sum in final output, but it was missing.");
      score -= 25;
    }

    if (reasons.length === 0) {
      reasons.push("Execution output satisfies the requested goal.");
    }

    score = Math.max(0, Math.min(100, score));

    return {
      approved: score >= 70,
      score,
      reasons
    };
  }
}
```

