실무에서는 여기에 timeout, retry, 외부 API/tool 호출 등을 붙이면 됩니다.

```ts
import {
  ExecutionResult,
  Executor,
  Plan,
  PlanStep,
  StepExecutionResult,
  UserRequest
} from "./types.js";

function nowIso(): string {
  return new Date().toISOString();
}

function tokenize(input: string): string[] {
  return input
    .trim()
    .split(/\s+/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function extractNumbers(input: string): number[] {
  const matches = input.match(/-?\d+(\.\d+)?/g) ?? [];
  return matches.map(Number).filter((n) => Number.isFinite(n));
}

export class SimpleExecutor implements Executor {
  async execute(plan: Plan, request: UserRequest): Promise<ExecutionResult> {
    const stepResults: StepExecutionResult[] = [];
    const finalOutput: Record<string, unknown> = {};

    for (const step of plan.steps) {
      const result = await this.executeStep(step, request, finalOutput);
      stepResults.push(result);

      if (!result.success) {
        return {
          success: false,
          stepResults,
          finalOutput
        };
      }
    }

    return {
      success: true,
      stepResults,
      finalOutput
    };
  }

  private async executeStep(
    step: PlanStep,
    request: UserRequest,
    finalOutput: Record<string, unknown>
  ): Promise<StepExecutionResult> {
    const startedAt = nowIso();

    try {
      let output: unknown;

      switch (step.action) {
        case "PARSE_TEXT": {
          const tokens = tokenize(request.input);
          output = {
            tokens,
            tokenCount: tokens.length,
            originalLength: request.input.length
          };
          finalOutput.parsed = output;
          break;
        }

        case "COUNT_WORDS": {
          const parsed = finalOutput.parsed as
            | { tokens?: string[] }
            | undefined;

          const tokens = parsed?.tokens ?? tokenize(request.input);

          output = {
            wordCount: tokens.length
          };
          finalOutput.wordCount = tokens.length;
          break;
        }

        case "SUM_NUMBERS": {
          const numbers = extractNumbers(request.input);
          const sum = numbers.reduce((acc, n) => acc + n, 0);

          output = {
            numbers,
            sum
          };
          finalOutput.numbers = numbers;
          finalOutput.sum = sum;
          break;
        }

        default: {
          const exhaustiveCheck: never = step.action;
          throw new Error(`Unsupported action: ${exhaustiveCheck}`);
        }
      }

      return {
        stepId: step.id,
        success: true,
        output,
        startedAt,
        finishedAt: nowIso()
      };
    } catch (error) {
      return {
        stepId: step.id,
        success: false,
        output: null,
        error: error instanceof Error ? error.message : String(error),
        startedAt,
        finishedAt: nowIso()
      };
    }
  }
}
```

